import{_ as a,a as i,b as r,c as o}from"./chunks/Variant._HIU2fAQ.js";import{_ as t,o as n,c as s,a3 as l}from"./chunks/framework.g9mfNVRQ.js";const v=JSON.parse('{"title":"Download","description":"","frontmatter":{"source_hash":"932cfecc51","source_commit":"298bb92"},"headers":[],"relativePath":"it/install/download.md","filePath":"it/install/download.md"}'),c={name:"it/install/download.md"};function p(u,e,d,h,m,g){return n(),s("div",null,[...e[0]||(e[0]=[l('<h2 id="which-one-to-install" tabindex="-1">Quale installare? <a class="header-anchor" href="#which-one-to-install" aria-label="Permalink to &quot;Quale installare? {#which-one-to-install}&quot;">​</a></h2><p>xDrip non è disponibile sul Google Play Store. Trovi tutte le release su <a href="https://github.com/NightscoutFoundation/xDrip/releases" target="_blank" rel="noreferrer">Github</a>.<br> Per installare xDrip hai due scelte principali: l&#39;<strong>ultima release</strong> (Latest release) o una <strong>Pre-release</strong>.</p><div class="info custom-block"><p class="custom-block-title">Nota</p><p>Se hai già xDrip installato sul telefono, non devi disinstallarlo prima di installare un aggiornamento.<br> Se usi una versione fork e vuoi passare a una release ufficiale di xDrip, o viceversa, segui <a href="./../troubleshoot/reinstall.html">questa procedura</a>.</p></div><div class="info custom-block"><p class="custom-block-title">Più installazioni di xDrip</p><p>Se devi installare più di un xDrip sullo stesso telefono, ti serve una <a href="#variants">variante</a>.</p></div><h3 id="latest-release" tabindex="-1">Ultima release <a class="header-anchor" href="#latest-release" aria-label="Permalink to &quot;Ultima release {#latest-release}&quot;">​</a></h3><p>L&#39;ultima release (Latest release) è una versione stabile di xDrip. Non ha tutte le funzioni più recenti, ma ha una stabilità comprovata e non soffre di bug gravi. È una versione sicura con cui iniziare, a meno che non ti serva una funzione specifica (controlla il <a href="./../changelog.html">changelog</a>).</p><p>Puoi scaricarla da <a href="https://xdrip-plus-updates.appspot.com/stable/xdrip-plus-latest.apk" target="_blank" rel="noreferrer">qui</a> o con questo codice QR:</p><img src="https://jamorham.github.io/images/download-xdrip-plus-qr-code-120.png"><p>La trovi anche nel <a href="https://github.com/NightscoutFoundation/xDrip" target="_blank" rel="noreferrer">repository principale</a> selezionando Latest.</p><img src="'+a+'" style="zoom:50%;"><br><h4 id="download-warning" tabindex="-1">Avviso al download <a class="header-anchor" href="#download-warning" aria-label="Permalink to &quot;Avviso al download {#download-warning}&quot;">​</a></h4><p>xDrip scaricato da <a href="https://github.com/NightscoutFoundation/xDrip/releases" target="_blank" rel="noreferrer">https://github.com/NightscoutFoundation/xDrip/releases</a> è sicuro.</p><img src="'+i+'" style="zoom:75%;"><br><p>Una volta scaricato, <a href="./install.html">passa all&#39;installazione di xDrip</a></p><br><h3 id="pre-release" tabindex="-1">Pre-release <a class="header-anchor" href="#pre-release" aria-label="Permalink to &quot;Pre-release {#pre-release}&quot;">​</a></h3><p>Le pre-release includono gli sviluppi più recenti di xDrip, come traduzioni, nuove funzioni e correzioni di bug. E potrebbero anche contenere qualche bug... Resta comunque la versione da usare per beneficiare dei miglioramenti più recenti.</p><p>Tutte le versioni di xDrip sono disponibili <a href="https://github.com/NightscoutFoundation/xDrip/releases" target="_blank" rel="noreferrer">qui</a>.</p><p>Espandi gli asset (Assets) e seleziona il file <code>.apk</code>. Lo troverai nella cartella <code>Downloads</code> del telefono.</p><img src="'+r+'" style="zoom:50%;"><div class="info custom-block"><p class="custom-block-title">Nota</p><p><strong>Non</strong> usare i link di Facebook per scaricare xDrip, ma <strong>copia e incolla il link</strong> in un browser (come Chrome).</p></div><br><h4 id="download-warning-1" tabindex="-1">Avviso al download <a class="header-anchor" href="#download-warning-1" aria-label="Permalink to &quot;Avviso al download {#download-warning-1}&quot;">​</a></h4><p>xDrip scaricato da <a href="https://github.com/NightscoutFoundation/xDrip/releases" target="_blank" rel="noreferrer">https://github.com/NightscoutFoundation/xDrip/releases</a> è sicuro.</p><img src="'+i+'" style="zoom:75%;"><br><p>Una volta scaricato, <a href="./install.html">passa all&#39;installazione di xDrip</a></p><br><h2 id="forked-versions" tabindex="-1">Versioni fork <a class="header-anchor" href="#forked-versions" aria-label="Permalink to &quot;Versioni fork {#forked-versions}&quot;">​</a></h2><p>Alcuni sviluppatori aggiungono funzioni e personalizzazioni che non sono disponibili nelle pre-release ufficiali, finché l&#39;autore non crea una Pull Request in xDrip e questa viene integrata nel progetto principale.</p><div class="warning custom-block"><p class="custom-block-title">Aggiornare le versioni fork</p><p>Puoi usare queste versioni, ma devi sapere che potrebbero essere supportate solo dal loro autore.<br><strong>Gli aggiornamenti automatici di xDrip non funzionano con le versioni fork.</strong><br> Tieni anche presente che non puoi installare una versione fork se sul telefono hai installata una versione ufficiale:<br> dovrai prima <a href="./../troubleshoot/reinstall.html">disinstallarla</a>.<br> Lo stesso vale nel senso opposto (da fork a ufficiale).</p></div><br><h2 id="variants" tabindex="-1">Varianti <a class="header-anchor" href="#variants" aria-label="Permalink to &quot;Varianti {#variants}&quot;">​</a></h2><p>Vengono rilasciate regolarmente quattro varianti, che permettono di installare fino a 5 xDrip sul telefono. Può essere particolarmente utile per seguire più persone contemporaneamente.</p><div class="warning custom-block"><p class="custom-block-title">Attenzione</p><p>È sconsigliato usare una variante collegata al tuo sensore: usa solo la release principale.<br> Usa le varianti solo come follower.<br> Alcune prime versioni di xDrip perdevano valori quando si usava AAPS/NSClient. Usa le varianti più recenti.</p></div><p>Puoi scaricare le varianti <a href="https://drive.google.com/drive/folders/0B6mvYVNVC-fOWkxnVF80dlFabjQ?resourcekey=0-ebguuiPuB1wUI9Rp2zjMNg" target="_blank" rel="noreferrer">qui</a>.</p><p>Ordinale per ultima modifica e scegli la variante da scaricare.</p><img src="'+o+'" style="zoom:90%;"><p>Le varianti sono incluse anche come asset accanto all&#39;apk normale nell&#39;ultima release su <a href="https://github.com/NightscoutFoundation/xDrip/releases" target="_blank" rel="noreferrer">GitHub</a>.</p><img src="'+a+'" style="zoom:50%;"><p>Una volta scaricata una variante, procedi come per una normale installazione di xDrip.</p><p><strong>Le varianti non si aggiornano automaticamente.</strong> Devi scaricare e installare gli aggiornamenti sopra la versione attuale della variante (non serve disinstallarla): assicurati solo di selezionare la stessa variante (da 1 a 4).</p><br><p><a href="https://github.com/NightscoutFoundation/xDrip/releases/tag/2023.02.26" target="_blank" rel="noreferrer"><em>Ultima modifica 3/2/2023</em></a></p>',46)])])}const k=t(c,[["render",p]]);export{v as __pageData,k as default};
